      "python": "from collections import deque\nimport heapq\n\nclass Graph:\n    def __init__(self, vertices):\n        self.V = vertices\n        self.adj = {i: [] for i in range(vertices)}\n\n    def add_edge(self, u, v, w=1):\n        self.adj[u].append((v, w))\n\n    def bfs(self, start):\n        visited = [False] * self.V\n        q = deque([start])\n        visited[start] = True\n        res = []\n        while q:\n            u = q.popleft()\n            res.append(u)\n            for v, _ in self.adj[u]:\n                if not visited[v]:\n                    visited[v] = True\n                    q.append(v)\n        return res\n\n    def dfs(self, start):\n        visited = [False] * self.V\n        res = []\n        def _dfs(u):\n            visited[u] = True\n            res.append(u)\n            for v, _ in self.adj[u]:\n                if not visited[v]:\n                    _dfs(v)\n        _dfs(start)\n        return res\n\n    def dijkstra(self, src):\n        dist = [float('inf')] * self.V\n        dist[src] = 0\n        pq = [(0, src)]\n        while pq:\n            d, u = heapq.heappop(pq)\n            if d > dist[u]: continue\n            for v, w in self.adj[u]:\n                if dist[u] + w < dist[v]:\n                    dist[v] = dist[u] + w\n                    heapq.heappush(pq, (dist[v], v))\n        return dist",
