      "python": "from collections import deque\nimport heapq\n\nclass Graph:\n    def __init__(self, vertices):\n        self.V = vertices\n        self.adj = {i: [] for i in range(vertices)}\n\n    def add_edge(self, u, v, w=1):\n        self.adj[u].append((v, w))\n\n    def bfs(self, start):\n        visited = [False] * self.V\n        q = deque([start])\n        visited[start] = True\n        res = []\n        while q:\n            u = q.popleft()\n            res.append(u)\n            for v, _ in self.adj[u]:\n                if not visited[v]:\n                    visited[v] = True\n                    q.append(v)\n        return res\n\n    def dfs(self, start):\n        visited = [False] * self.V\n        res = []\n        def _dfs(u):\n            visited[u] = True\n            res.append(u)\n            for v, _ in self.adj[u]:\n                if not visited[v]:\n                    _dfs(v)\n        _dfs(start)\n        return res\n\n    def dijkstra(self, src):\n        dist = [float('inf')] * self.V\n        dist[src] = 0\n        pq = [(0, src)]\n        while pq:\n            d, u = heapq.heappop(pq)\n            if d > dist[u]: continue\n            for v, w in self.adj[u]:\n                if dist[u] + w < dist[v]:\n                    dist[v] = dist[u] + w\n                    heapq.heappush(pq, (dist[v], v))\n        return dist",
      "c": "#include <stdio.h>\n#include <stdlib.h>\n\n#define MAX_V 100\nint adj[MAX_V][MAX_V];\nint V;\n\nvoid bfs(int start) {\n    int visited[MAX_V] = {0};\n    int q[MAX_V], front = 0, rear = 0;\n    q[rear++] = start;\n    visited[start] = 1;\n    while (front < rear) {\n        int u = q[front++];\n        printf(\"%d \", u);\n        for (int v = 0; v < V; v++) {\n            if (adj[u][v] && !visited[v]) {\n                visited[v] = 1;\n                q[rear++] = v;\n            }\n        }\n    }\n}\n\nvoid dfs_rec(int u, int visited[]) {\n    visited[u] = 1;\n    printf(\"%d \", u);\n    for (int v = 0; v < V; v++) {\n        if (adj[u][v] && !visited[v]) dfs_rec(v, visited);\n    }\n}",
      "cpp": "#include <vector>\n#include <queue>\n#include <iostream>\n\nusing namespace std;\n\nclass Graph {\n    int V;\n    vector<vector<pair<int,int>>> adj;\npublic:\n    Graph(int v) : V(v), adj(v) {}\n    void addEdge(int u, int v, int w=1) { adj[u].push_back({v,w}); }\n    void bfs(int start) {\n        vector<bool> vis(V, false);\n        queue<int> q;\n        q.push(start); vis[start] = true;\n        while(!q.empty()) {\n            int u = q.front(); q.pop();\n            cout << u << \" \";\n            for(auto& edge : adj[u]) {\n                if(!vis[edge.first]) { vis[edge.first] = true; q.push(edge.first); }\n            }\n        }\n    }\n};",
      "java": "import java.util.*;\n\npublic class Graph {\n    int V;\n    List<List<int[]>> adj;\n    public Graph(int v) {\n        V = v;\n        adj = new ArrayList<>();\n        for(int i=0; i<v; i++) adj.add(new ArrayList<>());\n    }\n    public void addEdge(int u, int v, int w) { adj.get(u).add(new int[]{v, w}); }\n}",
      "javascript": "class Graph {\n    constructor(v) {\n        this.V = v;\n        this.adj = new Map();\n        for(let i=0; i<v; i++) this.adj.set(i, []);\n    }\n    addEdge(u, v, w=1) { this.adj.get(u).push({node: v, weight: w}); }\n}",
