      "rust": "use std::collections::HashMap;\n\npub struct LRUCache {\n    capacity: usize,\n    map: HashMap<i32, i32>,\n}\n\nimpl LRUCache {\n    pub fn new(capacity: usize) -> Self {\n        LRUCache {\n            capacity,\n            map: HashMap::new(),\n        }\n    }\n\n    pub fn get(&mut self, key: i32) -> i32 {\n        *self.map.get(&key).unwrap_or(&-1)\n    }\n\n    pub fn put(&mut self, key: i32, value: i32) {\n        self.map.insert(key, value);\n    }\n}\n"
